Create an ErrorBoundary component and wrap the Routes in App.tsx:
```typescript
// components/ErrorBoundary.tsx
class ErrorBoundary extends React.Component<{children: ReactNode}, {hasError: boolean}> {
    state = { hasError: false };
    static getDerivedStateFromError() { return { hasError: true }; }
    componentDidCatch(error: Error) { console.error("Page error:", error); }
    render() {
        if (this.state.hasError) {
            return <div>Something went wrong. <button onClick={() => this.setState({hasError: false})}>Retry</button></div>;
        }
        return this.props.children;
    }
}
```
Wrap `<Suspense>` and `<Routes>` inside `<ErrorBoundary>` in App.tsx.

Add memory limit to chat store (state/chat.ts). Cap at 50 threads, evict oldest:
```typescript
const MAX_THREADS = 50;
addMessage: (runId, message) => set((state) => {
    const threads = new Map(state.threads);
    // ... existing dedup logic ...
    // Evict oldest if over limit
    if (threads.size > MAX_THREADS) {
        const oldest = threads.keys().next().value;
        if (oldest && oldest !== runId) threads.delete(oldest);
    }
    return { threads };
}),
```

